import { useCallback, useEffect, useState } from 'react'
import type { PaymentMethod as PaymentMethodType } from '@shared/validations'
import { ShoppingCart, User } from 'lucide-react'
import { useCartStore } from '../store'
import { AddItemsSection } from '../components/AddItemsSection'
import { CartDisplay } from '../components/CartDisplay'
import { PosSection } from '../components/PosSection'
import { PosSidebar } from '../components/PosSidebar'
import { CustomerSelector } from '@/features/customers/components/CustomerSelector'
import type { CustomerDetail } from '@/features/customers/types'
import { PaymentDialog } from '../components/PaymentDialog'
import { submitCheckout, parseCheckoutSuccess } from '../services/checkout'

// ============================================================================
// Component — POS Page
// Premium dark layout:
//   • Left column: vertical stack of three glass sections
//       1. Customer (selector)
//       2. Add Items (search + barcode + special form)
//       3. Cart (line items table)
//   • Right sidebar: customer card + running totals + Pay button (sticky)
// ============================================================================

export function PosPage() {
  const customerId = useCartStore((s) => s.customerId)
  const setCustomer = useCartStore((s) => s.setCustomer)
  const startCheckout = useCartStore((s) => s.startCheckout)
  const finishCheckout = useCartStore((s) => s.finishCheckout)
  const failCheckout = useCartStore((s) => s.failCheckout)
  const getCheckoutPayload = useCartStore((s) => s.getCheckoutPayload)
  const lineItemCount = useCartStore((s) => s.lineItems.length)

  // Handle checkout submission
  const handleCheckout = useCallback(
    async (method: PaymentMethodType) => {
      startCheckout()

      try {
        const payload = getCheckoutPayload()
        // Override payment method from the form selection
        const checkoutPayload = { ...payload, paymentMethod: method }

        const response = await submitCheckout(checkoutPayload)
        const success = parseCheckoutSuccess(response)
        finishCheckout(success)
      } catch (err) {
        const message = err instanceof Error ? err.message : 'Unknown error during checkout'
        failCheckout(message)
      }
    },
    [startCheckout, finishCheckout, failCheckout, getCheckoutPayload]
  )

  const [paymentOpen, setPaymentOpen] = useState(false)

  // ── Cached selected customer (for sidebar display) ──
  // Fetches the FULL detail shape (email, phone, etc.) from GET /api/customers/:id.
  // The list endpoint returns the compact selector shape only.
  const [selectedCustomerCache, setSelectedCustomerCache] = useState<CustomerDetail | null>(null)

  useEffect(() => {
    if (!customerId) {
      setSelectedCustomerCache(null)
      return
    }

    let cancelled = false
    async function fetchCustomer() {
      try {
        const response = await fetch(`/api/customers/${encodeURIComponent(customerId!)}`)
        if (response.ok) {
          const data = (await response.json()) as CustomerDetail
          if (!cancelled) {
            setSelectedCustomerCache(data)
          }
        }
      } catch {
        // Silently fail
      }
    }
    fetchCustomer()
    return () => { cancelled = true }
  }, [customerId])

  return (
    <div className="dashboard-bg -m-6 min-h-full p-5 sm:p-7 lg:p-8">
      {/* Atmospheric glow orbs (subtle background motion) */}
      <div className="glow-orb glow-orb-cyan" aria-hidden />
      <div className="glow-orb glow-orb-violet" aria-hidden />

      {/* Page header */}
      <header className="relative z-[1] mb-6 animate-hero-reveal">
        <div className="mb-2 flex items-center gap-2">
          <span className="text-[10px] font-bold uppercase tracking-[.2em] text-cyan-400/70">
            Point of Sale
          </span>
          <span className="h-px w-8 bg-gradient-to-r from-cyan-400/60 to-transparent" />
        </div>
        <h1 className="bg-gradient-to-r from-cyan-300 via-blue-300 to-violet-300 bg-clip-text text-3xl font-extrabold tracking-tight text-transparent sm:text-4xl sm:leading-none">
          New Sale
        </h1>
        <p className="mt-2 text-sm text-muted-foreground/80">
          Scan, search, and check out — totals update live on the right.
        </p>
        <div className="mt-3 h-px w-40 animated-underline" aria-hidden />
      </header>

      {/* Main layout: left stack + right sidebar */}
      <div className="relative z-[1] flex gap-6">
        {/* Left column — vertical stack of three sections */}
        <div className="flex-1 min-w-0 flex flex-col gap-4 stagger-children">
          <PosSection
            icon={User}
            title="Customer"
            subtitle={customerId ? 'Customer attached' : 'Walk-in or pick a customer'}
          >
            <CustomerSelector
              customerId={customerId}
              onSelect={(id) => setCustomer(id)}
            />
          </PosSection>

          <PosSection
            icon={ShoppingCart}
            title="Add Items"
            subtitle="Scan barcode or search by name"
          >
            <AddItemsSection />
          </PosSection>

          <PosSection
            icon={ShoppingCart}
            title="Cart"
            subtitle={lineItemCount === 0 ? 'No items yet' : `${lineItemCount} ${lineItemCount === 1 ? 'item' : 'items'} in cart`}
            badge={
              lineItemCount > 0 ? (
                <span className="inline-flex items-center justify-center min-w-[1.5rem] h-6 px-2 rounded-full text-[11px] font-bold tabular-nums bg-cyan-500/15 text-cyan-300/95 ring-1 ring-cyan-400/30">
                  {lineItemCount}
                </span>
              ) : null
            }
          >
            <CartDisplay />
          </PosSection>
        </div>

        {/* Right column — sticky sidebar with customer + totals + Pay */}
        <PosSidebar
          selectedCustomer={selectedCustomerCache}
          hasCustomer={!!customerId}
          onPay={() => setPaymentOpen(true)}
        />
      </div>

      {/* Payment dialog */}
      <PaymentDialog
        open={paymentOpen}
        onClose={() => setPaymentOpen(false)}
        onCheckout={handleCheckout}
      />
    </div>
  )
}

/**
 * Customers — Frontend types.
 */

// ---------------------------------------------------------------------------
// Customer shapes (mirroring backend DTOs)
// ---------------------------------------------------------------------------

/** Compact customer shape for dropdown selectors. */
export interface CustomerSelectorItem {
  /** Unique customer identifier */
  id: string
  /** Human-readable name: "firstName lastName" for private, companyName for company */
  displayName: string
  /** 'private' or 'company' */
  type: 'private' | 'company'
}

/** Full customer detail returned by CRUD endpoints. */
export interface CustomerDetail {
  /** Unique customer identifier (client-generated UUID) */
  id: string
  /** Human-readable name: "firstName lastName" for private, companyName for company */
  displayName: string
  /** 'private' or 'company' */
  type: 'private' | 'company'
  /** First name — required for private customers */
  firstName?: string
  /** Last name — required for private customers */
  lastName?: string
  /** Company name — required for company customers */
  companyName?: string
  /** VAT ID — for company customers */
  vatId: string | null
  /** Phone number (loose validation: min 1, max 50 chars) */
  phone: string | null
  /** Email address (loose validation: min 1, max 50 chars) */
  email: string | null
  /** Street name */
  street: string | null
  /** Building/house number */
  number: string | null
  /** Apartment/unit number */
  bus: string | null
  /** Postal / ZIP code */
  postalCode: string | null
  /** City */
  city: string | null
  /** Country code (default: 'BE') */
  country: string
  /** Notification preference — sms or email */
  notificationPreference: 'sms' | 'email' | null
  // Index signature required by DataTable<T extends Record<string, unknown>>
  [key: string]: unknown
}

/** Display name computed from customer type and fields. */
export function getDisplayName(customer: CustomerDetail): string {
  return customer.type === 'private'
    ? [customer.firstName, customer.lastName].filter(Boolean).join(' ').trim() || ''
    : (customer.companyName ?? '')
}

// ---------------------------------------------------------------------------
// Pagination shapes
// ---------------------------------------------------------------------------

/** Paginated response from the management list endpoint. */
export interface CustomerPaginatedResponse {
  customers: CustomerDetail[]
  totalItems: number
  currentPage: number
  pageSize: number
  totalPages: number
}

// ---------------------------------------------------------------------------
// Customer Detail Panel — Activity types
// ---------------------------------------------------------------------------

/** Sale record for customer detail panel (from /sales?customerId=...) */
export interface CustomerSale {
  id: string
  saleNumber: string
  sourceType: 'direct_sale' | 'repair' | 'customer_order' | 'backorder'
  sourceId: string | null
  status: 'completed' | 'voided'
  subtotalNet: number
  vatTotal: number
  totalGross: number
  createdAt: number // epoch ms
}

/** Line item within a sale */
export interface SaleLineItem {
  id: string
  description: string
  quantity: number
  unitPriceNet: number
  lineNetTotal: number
  vatRateBps: number
  lineVatTotal: number
  lineGrossTotal: number
}

/** Payment record for a sale */
export interface SalePayment {
  id: string
  method: 'cash' | 'card' | 'bank_transfer'
  amount: number // cents
  allocatedAmount: number // cents
}

/** Enriched sale with line items and payments (fetched via /sales/:id) */
export interface CustomerSaleDetail {
  sale: CustomerSale
  lineItems: SaleLineItem[]
  payments: SalePayment[]
}

/** Bicycle owned by customer (from /bicycles?customerId=...) */
export interface CustomerBicycle {
  id: string
  source: 'inventory' | 'customer_owned'
  brand: string
  model: string
  year: number | null
  color: string | null
  isLease: boolean
  status: string
}

/** Repair record for customer detail panel */
export interface CustomerRepair {
  id: string
  bicycleId: string
  status: 'intake' | 'in_progress' | 'on_hold' | 'ready' | 'completed' | 'cancelled'
  plannedDate: number | null // epoch ms
  pickupDate: number | null
  completedAt: number | null
  createdAt: number
  bicycleBrand: string
  bicycleModel: string
}

/** Customer order for detail panel (from /orders?customerId=...) */
export interface CustomerOrder {
  id: string
  orderNumber: string
  status: 'pending' | 'ordered' | 'ready' | 'fulfilled' | 'cancelled'
  totalPriceNet: number // cents
  expectedDeliveryDate: number | null
  createdAt: number // epoch ms (timestamp)
}

/** Line item within a customer order */
export interface CustomerOrderLineItem {
  id: string
  description: string
  quantity: number
  unitPriceNet: number
  lineNetTotal: number
  vatRateBps: number
  lineVatTotal: number
  lineGrossTotal: number
}

/** Payment history entry for a customer order */
export interface OrderPaymentEntry {
  id: string
  method: 'cash' | 'card' | 'bank_transfer'
  amount: number // cents
  allocatedAmount: number // cents
}

