import type { CheckoutPayload, CheckoutSuccess } from '../store'

// ============================================================================
// Types — Server response shapes (raw JSON from Hono routes)
// ============================================================================

/** Response shape for a created sale */
export interface SaleResponse {
  /** The created sale header */
  sale: Record<string, unknown>
  /** The payment record for this sale */
  payment: Record<string, unknown>
  /** All line items for this sale */
  lineItems: Record<string, unknown>[]
}

/** Error response from POST /sales */
export interface SaleError {
  error: string
  code?: string
  shortfalls?: Array<{ partId: string; requested: number; available: number }>
}

// ============================================================================
// Checkout Service — calls POST /api/sales
// ============================================================================

const API_BASE = ''

/**
 * Submit a checkout to the server.
 *
 * Calls `POST /api/sales` with the cart payload and returns the created sale
 * data, or throws on failure.
 *
 * @param payload — Checkout payload from cart store
 * @returns Sale response with sale header, payment, and line items
 */
export async function submitCheckout(payload: CheckoutPayload): Promise<SaleResponse> {
  const response = await fetch(`${API_BASE}/api/sales`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
  })

  if (!response.ok) {
    const errorBody = (await response.json().catch(() => ({}))) as SaleError
    // Re-throw with the server's error message for display
    throw new Error(errorBody.error ?? `Checkout failed with status ${response.status}`)
  }

  return (await response.json()) as SaleResponse
}

/**
 * Extract sale number and total from a successful checkout response.
 */
export function parseCheckoutSuccess(response: SaleResponse): CheckoutSuccess {
  const sale = response.sale as Record<string, unknown>
  return {
    saleNumber: String(sale.sale_number ?? ''),
    totalGross: Number(sale.total_gross ?? 0),
  }
}

# Good and Bad Tests

## Good Tests

**Integration-style**: Test through real interfaces, not mocks of internal parts.

```typescript
// GOOD: Tests observable behavior
test("user can checkout with valid cart", async () => {
  const cart = createCart();
  cart.add(product);
  const result = await checkout(cart, paymentMethod);
  expect(result.status).toBe("confirmed");
});
```

Characteristics:

- Tests behavior users/callers care about
- Uses public API only
- Survives internal refactors
- Describes WHAT, not HOW
- One logical assertion per test

## Bad Tests

**Implementation-detail tests**: Coupled to internal structure.

```typescript
// BAD: Tests implementation details
test("checkout calls paymentService.process", async () => {
  const mockPayment = jest.mock(paymentService);
  await checkout(cart, payment);
  expect(mockPayment.process).toHaveBeenCalledWith(cart.total);
});
```

Red flags:

- Mocking internal collaborators
- Testing private methods
- Asserting on call counts/order
- Test breaks when refactoring without behavior change
- Test name describes HOW not WHAT
- Verifying through external means instead of interface

```typescript
// BAD: Bypasses interface to verify
test("createUser saves to database", async () => {
  await createUser({ name: "Alice" });
  const row = await db.query("SELECT * FROM users WHERE name = ?", ["Alice"]);
  expect(row).toBeDefined();
});

// GOOD: Verifies through interface
test("createUser makes user retrievable", async () => {
  const user = await createUser({ name: "Alice" });
  const retrieved = await getUser(user.id);
  expect(retrieved.name).toBe("Alice");
});
```

