    // 30 min at €60/hr = (30/60) * 60000 = 30000 cents net for qty=1
    useCartStore.getState().addLaborLineItem({
      description: 'Tune-up',
      minutesWorked: 60,
      hourlyRateSnapshot: 50000, // €50/hr
    })

    const state = useCartStore.getState()
    const item = state.lineItems[0]
    // priceNet = (minutesWorked / 60) * hourlyRateSnapshot = (60/60) * 50000 = 50000
    expect(item.priceNet).toBe(50000)
    // lineTotalNet = 50000 * 1 = 50000
    expect(item.lineTotalNet).toBe(50000)
    // VAT: 50000 × 2100 / 10000 = 10500
    expect(item.lineTotalVat).toBe(10500)
    // Gross: 50000 + 10500 = 60500
    expect(item.lineTotalGross).toBe(60500)
  })

  it('adds labor with optional service ID', () => {
    useCartStore.getState().addLaborLineItem({
      description: 'Chain replacement',
      minutesWorked: 20,
